SELECT no_plan();
CREATE TEMP TABLE guest_renewal_fixture(booking_id uuid,period_id uuid,guest_user uuid,admin_user uuid,other_user uuid,attempt jsonb,original_booking jsonb);
GRANT ALL ON guest_renewal_fixture TO authenticated,service_role;
DO $$
DECLARE b public.bookings%ROWTYPE; actor uuid; guest uuid; other uuid; planned jsonb; period uuid;
BEGIN
 SELECT * INTO b FROM public.bookings WHERE reservation_number='ZNX-000150';
 SELECT user_id INTO actor FROM public.profiles WHERE is_admin LIMIT 1;
 SELECT user_id INTO guest FROM public.profiles WHERE id=b.renter_profile_id;
 SELECT user_id INTO other FROM public.profiles WHERE id<>b.renter_profile_id AND NOT is_admin LIMIT 1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 planned:=public.admin_schedule_rental_extension(b.id,b.end_date+30,b.dropoff_time,158400,true,'Synthetic Guest renewal checkout test');
 PERFORM public.admin_activate_rental_extension((planned->>'plan_id')::uuid);
 SELECT id INTO period FROM public.rental_extension_periods WHERE extension_plan_id=(planned->>'plan_id')::uuid ORDER BY period_number LIMIT 1;
 UPDATE public.bookings SET stripe_customer_id='cus_synthetic',stripe_payment_method_id='pm_synthetic' WHERE id=b.id;
 INSERT INTO guest_renewal_fixture SELECT b.id,period,guest,actor,other,NULL,to_jsonb(x) FROM public.bookings x WHERE x.id=b.id;
END $$;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',other_user,'role','authenticated')::text,true) FROM guest_renewal_fixture;
SET LOCAL ROLE authenticated;
SELECT throws_like('SELECT get_guest_renewal_details(period_id) FROM guest_renewal_fixture','%different account%','Another account cannot read renewal terms');
SELECT throws_like('SELECT prepare_guest_renewal_checkout(period_id,guest_user,false) FROM guest_renewal_fixture','%permission denied%','Browser cannot impersonate guest to create a payment');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',guest_user,'role','authenticated')::text,true) FROM guest_renewal_fixture;
SET LOCAL ROLE authenticated;
SELECT is((SELECT get_guest_renewal_details(period_id)->>'can_pay' FROM guest_renewal_fixture),'true','Guest can review active renewal without stored-card collection');
SELECT is((SELECT get_guest_renewal_details(period_id)->>'amount_cents' FROM guest_renewal_fixture),'158400','Server returns exact period amount');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_like('SELECT prepare_guest_renewal_checkout(period_id,admin_user,false) FROM guest_renewal_fixture','%Only the reservation guest%','Admin cannot start payment as customer');
UPDATE guest_renewal_fixture SET attempt=prepare_guest_renewal_checkout(period_id,guest_user,false);
SELECT is((SELECT prepare_guest_renewal_checkout(period_id,guest_user,false)->>'attempt_id' FROM guest_renewal_fixture),(SELECT attempt->>'attempt_id' FROM guest_renewal_fixture),'Concurrent/repeated creation reuses one attempt');
SELECT is((SELECT count(*)::integer FROM renewal_checkout_attempts WHERE period_id=(SELECT period_id FROM guest_renewal_fixture)),1,'One active checkout per period');
SELECT throws_like('SELECT attach_guest_renewal_session((attempt->>''attempt_id'')::uuid,''cs_live_forged'',''https://checkout.stripe.com/c/pay/fake'',now()+interval ''1 hour'') FROM guest_renewal_fixture','%identity conflicts%','Live/test mode mismatch rejected');
SELECT attach_guest_renewal_session((attempt->>'attempt_id')::uuid,'cs_test_renewal','https://checkout.stripe.com/c/pay/cs_test_renewal',now()+interval '1 hour') FROM guest_renewal_fixture;
SELECT throws_like('SELECT record_guest_renewal_evidence((attempt->>''attempt_id'')::uuid,''cs_test_renewal'',''pi_fake'',1,''usd'',false,''paid'') FROM guest_renewal_fixture','%evidence conflicts%','Cannot underpay a renewal or change amount');
SELECT record_guest_renewal_evidence((attempt->>'attempt_id')::uuid,'cs_test_renewal',NULL,158400,'usd',false,'processing') FROM guest_renewal_fixture;
SELECT is((SELECT payment_status FROM rental_extension_periods WHERE id=(SELECT period_id FROM guest_renewal_fixture)),'processing','Unconfirmed asynchronous payment is not paid');
SELECT ok((SELECT paid_at IS NULL FROM rental_extension_periods WHERE id=(SELECT period_id FROM guest_renewal_fixture)),'No paid timestamp before confirmed payment');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',admin_user,'role','authenticated')::text,true) FROM guest_renewal_fixture;
SET LOCAL ROLE authenticated;
SELECT throws_like('SELECT admin_prepare_renewal_payment(period_id) FROM guest_renewal_fixture','%Guest renewal checkout already exists%','Admin stored-card charge cannot race guest checkout');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT record_guest_renewal_evidence((attempt->>'attempt_id')::uuid,'cs_test_renewal','pi_renewal',158400,'usd',false,'paid') FROM guest_renewal_fixture;
SELECT is((SELECT payment_status FROM rental_extension_periods WHERE id=(SELECT period_id FROM guest_renewal_fixture)),'paid','Exact verified evidence settles only renewal period');
SELECT is((SELECT record_guest_renewal_evidence((attempt->>'attempt_id')::uuid,'cs_test_renewal','pi_renewal',158400,'usd',false,'paid')->>'already_paid' FROM guest_renewal_fixture),'true','Duplicate webhook does not duplicate payment');
SELECT record_guest_renewal_evidence((attempt->>'attempt_id')::uuid,'cs_test_renewal',NULL,158400,'usd',false,'failed') FROM guest_renewal_fixture;
SELECT is((SELECT payment_status FROM rental_extension_periods WHERE id=(SELECT period_id FROM guest_renewal_fixture)),'paid','Late failure cannot downgrade confirmed paid state');
SELECT is((SELECT count(*)::integer FROM rental_extension_events WHERE period_id=(SELECT period_id FROM guest_renewal_fixture) AND event_type='payment_succeeded'),1,'Single immutable success audit');
SELECT is((SELECT to_jsonb(b) FROM bookings b WHERE id=(SELECT booking_id FROM guest_renewal_fixture)),(SELECT original_booking FROM guest_renewal_fixture),'Entire original booking and deposit fields remain unchanged');
SELECT is((SELECT prepare_guest_renewal_checkout(period_id,guest_user,false)->>'already_paid' FROM guest_renewal_fixture),'true','Paid link never creates another session');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_like('SELECT record_guest_renewal_evidence((attempt->>''attempt_id'')::uuid,''cs_test_renewal'',''pi_fake'',158400,''usd'',false,''paid'') FROM guest_renewal_fixture','%permission denied%','Clients cannot forge settlement evidence');
RESET ROLE;
